// Package certs provides pre-generated test TLS credentials for SOK integration tests.
//
// The certs were generated with openssl (10-year validity, expires 2036-05-26):
//
//	openssl genrsa -out ca.key 2048
//	openssl req -new -x509 -days 3650 -key ca.key -subj "/CN=sok-test-ca/O=splunk" -out ca.crt
//	openssl genrsa -out server.key 2048
//	openssl req -new -key server.key -subj "/CN=splunk-test.cluster.local" -out server.csr
//	openssl x509 -req -days 3650 -in server.csr -CA ca.crt -CAkey ca.key -CAcreateserial \
//	  -extfile <(echo "[v3_req]\nsubjectAltName=DNS:splunk-test.cluster.local") \
//	  -extensions v3_req -out server.crt
//	openssl genrsa -out custom.key 2048
//	openssl req -new -x509 -days 3650 -key custom.key -subj "/CN=sok-test-custom/O=splunk" -out custom.crt
//
// These are test-only credentials — private keys are intentionally committed.
// Do NOT use these in production.
package certs

import "encoding/base64"

// decoded decodes a base64 string into []byte. Panics on invalid input (test fixtures only).
func decoded(s string) []byte {
	b, err := base64.StdEncoding.DecodeString(s)
	if err != nil {
		panic("test cert decode failure: " + err.Error())
	}
	return b
}

// ServerCRT is the PEM-encoded server certificate signed by TestCA.
// CN=splunk-test.cluster.local, SAN=*.splunk-test.cluster.local, expires 2036-05-26.
var ServerCRT = decoded("")

// ServerKey is the PEM-encoded RSA private key for ServerCRT.
var ServerKey = decoded("")

// CACrt is the PEM-encoded self-signed CA certificate that signed ServerCRT.
var CACrt = decoded("")

// CustomCRT is the PEM-encoded self-signed cert for the no-role mount test.
// CN=sok-test-custom, expires 2036-05-26.
var CustomCRT = decoded("")

// CustomKey is the PEM-encoded RSA private key for CustomCRT.
var CustomKey = decoded("")
